<?php
namespace App\Features\Stock\Services;
use App\Features\Stock\Models\Stock;use App\Features\Stock\Enums\StockStatus;use PhpOffice\PhpSpreadsheet\Spreadsheet;use PhpOffice\PhpSpreadsheet\Writer\Xlsx;use PhpOffice\PhpSpreadsheet\IOFactory;use Illuminate\Support\Facades\Validator;use Illuminate\Validation\ValidationException;
class StockExcelService {public function export(int $userId):string{$book=new Spreadsheet();$sheet=$book->getActiveSheet();$sheet->fromArray([['name','sku','description','qty','unit','price','min_stock','status'],...Stock::where('user_id',$userId)->get(['name','sku','description','quantity','unit','price','min_stock','status'])->map(fn($s)=>[$s->name,$s->sku,$s->description,$s->quantity,$s->unit,$s->price,$s->min_stock,$s->status->value])->all()]);$path=tempnam(sys_get_temp_dir(),'stock-').'.xlsx';(new Xlsx($book))->save($path);return $path;}public function import(string $path,int $userId):int{$rows=IOFactory::load($path)->getActiveSheet()->toArray(null,true,true,true);$count=0;foreach(array_slice($rows,1) as $row){$data=['name'=>trim((string)($row['A']??'')),'sku'=>trim((string)($row['B']??''))?:null,'description'=>(string)($row['C']??''),'quantity'=>(int)($row['D']??0),'unit'=>trim((string)($row['E']??'pcs'))?:'pcs','price'=>is_numeric($row['F']??null)?$row['F']:null,'min_stock'=>(int)($row['G']??5)];$v=Validator::make($data,['name'=>'required|string|max:150','quantity'=>'required|integer|min:0','min_stock'=>'required|integer|min:0','unit'=>'required|string|max:30','price'=>'nullable|numeric|min:0']);if($v->fails())continue;$data['user_id']=$userId;$data['status']=StockStatus::fromQuantity($data['quantity'],$data['min_stock']);Stock::create($data);$count++;}return $count;}}
